'use client';

import { useDroppable } from '@dnd-kit/core';
import { Layout } from 'lucide-react';
import { cn } from '@/lib/utils';
import { CanvasItem, Vendor } from '@/lib/types';
import { CanvasItemCard } from './CanvasItemCard';
import { SelectionBox } from './controls/SelectionBox';
import { GroupOutline } from './controls/GroupOutline';
import { MultiSelectIndicator } from './controls/MultiSelectIndicator';
import { SnapGuides, SnapGuide } from './controls/SnapGuides';

interface CanvasWorkspaceProps {
    canvasRef: React.RefObject<HTMLDivElement | null>;
    items: CanvasItem[];
    snapGuides?: SnapGuide[];
    activeDragRect?: { x: number; y: number; width: number; height: number } | null;
    selectedIds: string[];
    debugInfo: string;
    vendors: Vendor[];
    multiSelect: {
        toggleSelect: (id: string, isCtrlPressed: boolean) => void;
        startBoxSelection: (x: number, y: number) => void;
        updateBoxSelection: (x: number, y: number) => void;
        endBoxSelection: (ids: string[], isCtrlPressed: boolean) => void;
        selectionBox: any;
        isSelecting: boolean;
        clearSelection: () => void;
    };
    onClearItems: () => void;
    gridSnapEnabled?: boolean;
}

export function CanvasWorkspace({
    canvasRef,
    items,
    selectedIds,
    debugInfo,
    vendors,
    multiSelect,
    onClearItems,
    gridSnapEnabled = false,
    snapGuides = [],
    activeDragRect
}: CanvasWorkspaceProps) {
    const { setNodeRef, isOver } = useDroppable({
        id: 'canvas-droppable',
    });

    const getVendorName = (vendorId: string) => {
        return vendors.find(v => v.id === vendorId)?.name;
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        // Since items stop propagation, getting here means we clicked the background
        if (!e.ctrlKey) {
            multiSelect.clearSelection();
        }
        const rect = canvasRef.current?.getBoundingClientRect();
        if (rect) {
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            multiSelect.startBoxSelection(x, y);
        }
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (multiSelect.isSelecting) {
            const rect = canvasRef.current?.getBoundingClientRect();
            if (rect) {
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                multiSelect.updateBoxSelection(x, y);
            }
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (multiSelect.isSelecting && multiSelect.selectionBox) {
            const box = multiSelect.selectionBox;
            const itemsInBox = items.filter(item => {
                const itemWidth = 300; // Updated to match actual card width
                const itemHeight = 172; // Updated to match actual card height
                return (
                    item.x < box.x + box.width &&
                    item.x + itemWidth > box.x &&
                    item.y < box.y + box.height &&
                    item.y + itemHeight > box.y
                );
            }).map(i => i.id);
            multiSelect.endBoxSelection(itemsInBox, e.ctrlKey);
        }
    };

    return (
        <main
            ref={(node) => {
                setNodeRef(node);
                if (canvasRef && typeof canvasRef === 'object') {
                    // @ts-ignore
                    canvasRef.current = node;
                }
            }}
            className={cn(
                "flex-1 relative overflow-hidden bg-[radial-gradient(#333333_1px,transparent_1px)] [background-size:16px_16px] z-0 transition-colors duration-200",
                isOver && "bg-green-500/20"
            )}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
        >
            <div
                ref={canvasRef}
                className="absolute inset-0 w-full h-full"
            >
                {/* Grid Overlay */}
                <div
                    className={cn(
                        "absolute inset-0 pointer-events-none bg-[linear-gradient(to_right,#ffffff_1px,transparent_1px),linear-gradient(to_bottom,#ffffff_1px,transparent_1px)] bg-[size:20px_20px] z-[1] transition-opacity duration-300",
                        gridSnapEnabled ? "opacity-[0.08]" : "opacity-[0.02]"
                    )}
                />

                {/* Selection Box */}
                <SelectionBox box={multiSelect.selectionBox} />

                {/* Coordinate Display */}
                {selectedIds.length === 1 && (() => {
                    const item = items.find(i => i.id === selectedIds[0]);
                    if (!item) return null;
                    return (
                        <div className="absolute bottom-6 right-6 px-4 py-2 rounded-lg bg-black/40 backdrop-blur-md border border-white/10 text-xs font-mono text-white/60 flex flex-col gap-1 z-50 pointer-events-none select-none">
                            <div className="flex gap-4 justify-between">
                                <span>X: {Math.round(item.x)}</span>
                                <span>Y: {Math.round(item.y)}</span>
                            </div>
                            <div className="flex gap-4 justify-between opacity-70">
                                <span>W: 300</span>
                                <span>H: 172</span>
                            </div>
                        </div>
                    );
                })()}

                {/* Snap Guides Container - strictly clipped */}
                <div className="absolute inset-0 pointer-events-none overflow-hidden z-40">
                    <SnapGuides
                        guides={snapGuides}
                        canvasRect={canvasRef.current?.getBoundingClientRect()}
                        dragRect={activeDragRect}
                    />
                </div>

                {/* Multi-Select Indicator */}
                <MultiSelectIndicator count={selectedIds.length} />

                {/* Status Bar */}
                <div className="absolute top-4 left-6 right-6 flex items-center justify-between z-10 pointer-events-none">
                    <div className="flex items-center gap-4">
                        <div
                            className="px-3 py-1.5 rounded-full backdrop-blur-md border flex items-center gap-2"
                            style={{
                                backgroundColor: 'var(--color-surface)',
                                borderColor: 'var(--color-border)',
                                opacity: 0.9
                            }}
                        >
                            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                            <span
                                className="text-[10px] font-bold uppercase tracking-widest"
                                style={{ color: 'var(--color-text-secondary)' }}
                            >
                                Workspace Online
                            </span>
                        </div>
                        <div
                            className="px-3 py-1.5 rounded-full backdrop-blur-md border"
                            style={{
                                backgroundColor: 'var(--color-surface)',
                                borderColor: 'var(--color-border)',
                                opacity: 0.9
                            }}
                        >
                            <span
                                className="text-[10px] font-bold uppercase tracking-widest"
                                style={{ color: 'var(--color-text-secondary)' }}
                            >
                                {items.length} Assets Mapped
                            </span>
                        </div>
                        <div className="px-3 py-1.5 rounded-full bg-blue-500/10 backdrop-blur-md border border-blue-500/20">
                            <span className="text-[10px] font-bold text-blue-400 uppercase tracking-widest">{debugInfo}</span>
                        </div>
                        {isOver && (
                            <div className="px-3 py-1.5 rounded-full bg-green-500/20 backdrop-blur-md border border-green-500/50">
                                <span className="text-[10px] font-bold text-green-400 uppercase tracking-widest">DROP ZONE ACTIVE</span>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            onClearItems();
                        }}
                        className="pointer-events-auto px-4 py-1.5 rounded-xl bg-white/5 border border-white/10 text-[10px] font-bold text-white/40 uppercase tracking-widest hover:bg-red-500/20 hover:text-red-400 hover:border-red-500/50 transition-all"
                    >
                        Clear Workspace
                    </button>
                </div>

                {/* Group Outlines */}
                {Array.from(new Set(items.filter(it => it.groupId).map(it => it.groupId))).map(groupId => (
                    <GroupOutline key={groupId} items={items} groupId={groupId!} />
                ))}

                {/* Canvas Items */}
                {items.map((item) => (
                    <CanvasItemCard
                        key={item.id}
                        item={item}
                        isSelected={selectedIds.includes(item.id)}
                        onClick={(e) => {
                            multiSelect.toggleSelect(item.id, e.ctrlKey);
                        }}
                        vendorName={item.entityType === 'product' ? getVendorName(item.data.payload?.vendorId) : undefined}
                    />
                ))}

                {/* Empty State */}
                {items.length === 0 && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                        <div className="w-32 h-32 mb-6 rounded-full bg-white/[0.02] border border-white/[0.05] flex items-center justify-center">
                            <Layout className="w-10 h-10 text-white/10" />
                        </div>
                        <h3 className="text-lg font-medium text-white/40 mb-2">Initialize Canvas</h3>
                        <p className="text-sm text-white/20">Drag components from the sidebar to begin designing</p>
                    </div>
                )}
            </div>
        </main>
    );
}
